(1236,1120,'_form','<div class=\"contact-form-grid\">\n    <div class=\"cf-field-group\">\n        <label class=\"cf-label\">Họ và tên <span class=\"cf-required\">*</span></label>\n        [text* your-name class:cf-input placeholder \"Ví dụ: Nguyễn Văn A\"]\n    </div>\n    <div class=\"cf-field-group\">\n        <label class=\"cf-label\">Địa chỉ Email <span class=\"cf-required\">*</span></label>\n        [email* your-email class:cf-input placeholder \"name@example.com\"]\n    </div>\n</div>\n<div class=\"cf-field-group\">\n    <label class=\"cf-label\">Chủ đề liên hệ <span class=\"cf-required\">*</span></label>\n    [text* your-subject class:cf-input placeholder \"Ví dụ: Tuyển dụng / Tìm việc / Hợp tác doanh nghiệp...\"]\n</div>\n<div class=\"cf-field-group\">\n    <label class=\"cf-label\">Nội dung tin nhắn <span class=\"cf-required\">*</span></label>\n    [textarea* your-message class:cf-textarea placeholder \"Nhập chi tiết nội dung bạn cần hỗ trợ...\"]\n</div>\n<div class=\"cf-submit-wrap\">\n    [submit class:cf-submit-btn \"GỬI LIÊN HỆ NGAY\"]\n</div>'),
(1237,1120,'_mail','a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:59:\"[_site_title] Yêu Cầu Liên Hệ Mới: \"[your-subject]\"\";s:6:\"sender\";s:41:\"[_site_title] <wordpress@wordpress.local>\";s:9:\"recipient\";s:19:\"[_site_admin_email]\";s:4:\"body\";s:4118:\"<div style=\"background-color: #f1f5f9; padding: 35px 15px; font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Helvetica, Arial, sans-serif;\">\n  <div style=\"max-width: 600px; margin: 0 auto; background-color: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 20px rgba(0,0,0,0.06); border: 1px solid #e2e8f0;\">\n    \n    <!-- HEADER -->\n    <div style=\"background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%); padding: 30px; text-align: center; border-bottom: 4px solid #ea6a1b;\">\n      <h1 style=\"color: #ffffff; margin: 0; font-size: 24px; font-weight: 800; letter-spacing: 1px; text-transform: uppercase;\">[_site_title]</h1>\n      <p style=\"color: #94a3b8; margin: 8px 0 0; font-size: 13.5px; font-weight: 500;\">Thông Báo Yêu Cầu Liên Hệ Mới Từ Khách Hàng</p>\n    </div>\n\n    <!-- BODY -->\n    <div style=\"padding: 32px 30px;\">\n      <p style=\"color: #334155; font-size: 15px; line-height: 1.6; margin: 0 0 22px;\">\n        Xin chào <strong>Quản trị viên</strong>, bạn vừa nhận được một yêu cầu liên hệ mới qua trang web với thông tin chi tiết dưới đây:\n      </p>\n\n      <!-- BẢNG THÔNG TIN KHÁCH HÀNG -->\n      <table style=\"width: 100%; border-collapse: collapse; margin-bottom: 25px; font-size: 14px; border: 1px solid #e2e8f0; border-radius: 8px; overflow: hidden;\">\n        <tr style=\"border-bottom: 1px solid #e2e8f0; background-color: #f8fafc;\">\n          <td style=\"padding: 12px 16px; color: #64748b; font-weight: 600; width: 35%;\">👤 Họ và tên:</td>\n          <td style=\"padding: 12px 16px; color: #0f172a; font-weight: 700; font-size: 15px;\">[your-name]</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid #e2e8f0;\">\n          <td style=\"padding: 12px 16px; color: #64748b; font-weight: 600;\">✉️ Địa chỉ Email:</td>\n          <td style=\"padding: 12px 16px; color: #ea6a1b; font-weight: 600;\">\n            <a href=\"mailto:[your-email]\" style=\"color: #ea6a1b; text-decoration: none;\">[your-email]</a>\n          </td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid #e2e8f0; background-color: #f8fafc;\">\n          <td style=\"padding: 12px 16px; color: #64748b; font-weight: 600;\">📌 Chủ đề:</td>\n          <td style=\"padding: 12px 16px; color: #0f172a; font-weight: 600;\">[your-subject]</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 12px 16px; color: #64748b; font-weight: 600;\">⏰ Thời gian gửi:</td>\n          <td style=\"padding: 12px 16px; color: #64748b;\">[_date] lúc [_time]</td>\n        </tr>\n      </table>\n\n      <!-- KHUNG LỜI NHẮN -->\n      <div style=\"margin-bottom: 28px;\">\n        <div style=\"font-size: 14px; font-weight: 700; color: #1e293b; margin-bottom: 10px;\">📝 Nội dung tin nhắn:</div>\n        <div style=\"background-color: #f8fafc; border-left: 4px solid #ea6a1b; border-radius: 4px; padding: 18px 20px; color: #334155; font-size: 14.5px; line-height: 1.65; white-space: pre-wrap; font-style: italic;\">\"[your-message]\"</div>\n      </div>\n\n      <!-- NÚT PHẢN HỒI -->\n      <div style=\"text-align: center; margin-top: 32px;\">\n        <a href=\"mailto:[your-email]?subject=Re: [your-subject]\" style=\"display: inline-block; background-color: #ea6a1b; color: #ffffff; text-decoration: none; padding: 13px 32px; border-radius: 6px; font-weight: 700; font-size: 14.5px; box-shadow: 0 4px 12px rgba(234, 106, 27, 0.35); text-transform: uppercase; letter-spacing: 0.5px;\">\n          ✉️ Trả Lời Khách Hàng Ngay\n        </a>\n      </div>\n    </div>\n\n    <!-- FOOTER -->\n    <div style=\"background-color: #f8fafc; border-top: 1px solid #e2e8f0; padding: 20px 30px; text-align: center;\">\n      <p style=\"color: #94a3b8; font-size: 12.5px; margin: 0; line-height: 1.5;\">\n        Email này được gửi tự động từ hệ thống website <a href=\"[_site_url]\" style=\"color: #ea6a1b; text-decoration: none; font-weight: 600;\">[_site_title]</a>.<br>\n        Bạn có thể bấm trả lời trực tiếp email này để phản hồi thư cho <strong>[your-name]</strong>.\n      </p>\n    </div>\n\n  </div>\n</div>\";s:18:\"additional_headers\";s:22:\"Reply-To: [your-email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:1;s:13:\"exclude_blank\";b:1;}'),
