(2050,1167,'_form','<div class=\"apply-form-row\">\n    <div class=\"apply-form-group\">\n        <label>Họ và tên <span class=\"cf-req\">*</span></label>\n        [text* your-name class:apply-input placeholder \"Nguyễn Văn A\"]\n    </div>\n    <div class=\"apply-form-group\">\n        <label>Email liên hệ <span class=\"cf-req\">*</span></label>\n        [email* your-email class:apply-input placeholder \"email@domain.com\"]\n    </div>\n</div>\n\n<div class=\"apply-form-row\">\n    <div class=\"apply-form-group\">\n        <label>Số điện thoại</label>\n        [tel your-phone class:apply-input placeholder \"0987 654 321\"]\n    </div>\n    <div class=\"apply-form-group\">\n        <label>Vị trí ứng tuyển</label>\n        [text your-job class:apply-input placeholder \"Tên vị trí công việc\"]\n    </div>\n</div>\n\n<div class=\"apply-form-group\">\n    <label>Tải lên hồ sơ CV (PDF, DOC, DOCX - Tối đa 10MB) <span class=\"cf-req\">*</span></label>\n    [file* your-cv filetypes:pdf|doc|docx limit:10mb class:apply-file-input]\n</div>\n\n<div class=\"apply-form-group\">\n    <label>Thư giới thiệu / Lời nhắn cho nhà tuyển dụng</label>\n    [textarea your-message class:apply-textarea x3 placeholder \"Nêu ngắn gọn lý do bạn phù hợp với vị trí này...\"]\n</div>\n\n<div class=\"apply-form-footer\">\n    [submit class:btn-submit-apply \"GỬI HỒ SƠ ỨNG TUYỂN\"]\n</div>'),
(2051,1167,'_mail','a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:46:\"[Ứng tuyển mới] [your-job] - [your-name]\";s:6:\"sender\";s:41:\"[_site_title] <wordpress@wordpress.local>\";s:9:\"recipient\";s:20:\"nhanbao410@gmail.com\";s:4:\"body\";s:3462:\"<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n</head>\n<body style=\"font-family: Arial, sans-serif; line-height: 1.6; color: #333333; margin: 0; padding: 20px; background-color: #f4f6f8;\">\n    <div style=\"max-width: 650px; margin: 0 auto; background: #ffffff; border-radius: 8px; overflow: hidden; box-shadow: 0 4px 10px rgba(0,0,0,0.06); border: 1px solid #e5e7eb;\">\n        <div style=\"background-color: #ea580c; padding: 24px 30px; text-align: center;\">\n            <h2 style=\"color: #ffffff; margin: 0; font-size: 20px; font-weight: 700; text-transform: uppercase;\">ỨNG VIÊN NỘP HỒ SƠ TUYỂN DỤNG</h2>\n            <p style=\"color: rgba(255,255,255,0.9); margin: 6px 0 0 0; font-size: 14px;\">Thông tin ứng tuyển từ [_site_title]</p>\n        </div>\n        <div style=\"padding: 30px;\">\n            <div style=\"background-color: #fff7ed; border-left: 4px solid #ea580c; padding: 14px 18px; margin-bottom: 24px; border-radius: 0 4px 4px 0;\">\n                <span style=\"font-size: 13px; color: #9a3412; font-weight: 600; text-transform: uppercase; display: block;\">Vị trí ứng tuyển</span>\n                <strong style=\"font-size: 17px; color: #1f2937;\">[your-job]</strong>\n            </div>\n            <table style=\"width: 100%; border-collapse: collapse; margin-bottom: 20px;\">\n                <tr>\n                    <td style=\"padding: 10px 0; border-bottom: 1px solid #f3f4f6; width: 140px; color: #6b7280; font-weight: 600;\">Họ và tên:</td>\n                    <td style=\"padding: 10px 0; border-bottom: 1px solid #f3f4f6; color: #111827; font-weight: 700;\">[your-name]</td>\n                </tr>\n                <tr>\n                    <td style=\"padding: 10px 0; border-bottom: 1px solid #f3f4f6; color: #6b7280; font-weight: 600;\">Email:</td>\n                    <td style=\"padding: 10px 0; border-bottom: 1px solid #f3f4f6; color: #ea580c;\"><a href=\"mailto:[your-email]\" style=\"color: #ea580c; text-decoration: none; font-weight: 600;\">[your-email]</a></td>\n                </tr>\n                <tr>\n                    <td style=\"padding: 10px 0; border-bottom: 1px solid #f3f4f6; color: #6b7280; font-weight: 600;\">Số điện thoại:</td>\n                    <td style=\"padding: 10px 0; border-bottom: 1px solid #f3f4f6; color: #111827; font-weight: 600;\">[your-phone]</td>\n                </tr>\n            </table>\n            <div style=\"margin-top: 20px;\">\n                <span style=\"font-size: 13px; color: #6b7280; font-weight: 600; text-transform: uppercase; display: block; margin-bottom: 8px;\">Lời nhắn từ ứng viên:</span>\n                <div style=\"background: #f9fafb; padding: 15px; border-radius: 6px; border: 1px solid #e5e7eb; color: #374151; font-size: 14px; white-space: pre-wrap;\">[your-message]</div>\n            </div>\n            <div style=\"margin-top: 25px; padding: 15px; background: #ecfdf5; border: 1px solid #a7f3d0; border-radius: 6px; text-align: center;\">\n                <span style=\"color: #065f46; font-size: 13.5px; font-weight: 600;\">📎 Tệp CV đính kèm đã được tự động gắn vào email này.</span>\n            </div>\n        </div>\n        <div style=\"background-color: #f9fafb; padding: 16px 30px; text-align: center; border-top: 1px solid #f3f4f6; font-size: 12px; color: #9ca3af;\">\n            Email được gửi tự động từ hệ thống tuyển dụng <strong>[_site_title]</strong>\n        </div>\n    </div>\n</body>\n</html>\";s:18:\"additional_headers\";s:46:\"Reply-To: [your-email]\nContent-Type: text/html\";s:11:\"attachments\";s:9:\"[your-cv]\";s:8:\"use_html\";b:1;s:13:\"exclude_blank\";b:0;}'),
(2052,1167,'_messages','a:6:{s:12:\"mail_sent_ok\";s:82:\"Chúc mừng! Hồ sơ ứng tuyển của bạn đã được gửi thành công.\";s:12:\"mail_sent_ng\";s:65:\"Có lỗi xảy ra khi gửi hồ sơ. Vui lòng thử lại sau.\";s:16:\"validation_error\";s:82:\"Vui lòng kiểm tra lại các trường bắt buộc và định dạng file CV.\";s:13:\"upload_failed\";s:46:\"Có lỗi khi tải file CV lên hệ thống.\";s:24:\"upload_file_type_invalid\";s:63:\"Chỉ chấp nhận tệp định dạng PDF, DOC, hoặc DOCX.\";s:21:\"upload_file_too_large\";s:52:\"Kích thước tệp CV quá lớn (tối đa 10MB).\";}'),
